export const SEVERITY_LEVELS = ['low', 'medium', 'high', 'critical'] as const;

export type Severity = (typeof SEVERITY_LEVELS)[number];

/** Narrow an untrusted value (e.g. a nullable DB column) to a known severity. */
function isSeverity(value: unknown): value is Severity {
  return SEVERITY_LEVELS.some((level) => level === value);
}

/** Coerce an untrusted value to a severity, falling back when it is null/unrecognised. */
function toSeverity(value: unknown, fallback: Severity = 'medium'): Severity {
  return isSeverity(value) ? value : fallback;
}

